import{_ as e,H as t,f as i,i as l}from"./chunks/framework.Cvt1eIE0.js";const c=JSON.parse('{"title":"第七章：多轮对话技巧","description":"学会通过多轮对话完善代码","frontmatter":{"title":"第七章：多轮对话技巧","description":"学会通过多轮对话完善代码"},"headers":[],"relativePath":"guide/2-basic-usage/7-multi-turn.md","filePath":"guide/2-basic-usage/7-multi-turn.md"}'),s={name:"guide/2-basic-usage/7-multi-turn.md"};function o(n,a,r,d,p,h){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="第七章-多轮对话技巧" tabindex="-1">第七章：多轮对话技巧 <a class="header-anchor" href="#第七章-多轮对话技巧" aria-label="Permalink to &quot;第七章：多轮对话技巧&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你会通过多轮对话一步步完善代码。</p></div><h2 id="为什么多轮对话更有效" tabindex="-1">为什么多轮对话更有效？ <a class="header-anchor" href="#为什么多轮对话更有效" aria-label="Permalink to &quot;为什么多轮对话更有效？&quot;">​</a></h2><p>想象你要建一座房子：</p><ul><li><strong>一次性描述</strong>：给我建一座房子 → 出来的可能不是你想要的</li><li><strong>一步步来</strong>：先打地基 → 地基好了，继续砌墙 → 墙好了，继续装修 → 每一步都能调整</li></ul><p>多轮对话就是这种方式，让 Claude 一步步帮你完善。</p><h2 id="场景演练-做一个待办事项" tabindex="-1">场景演练：做一个待办事项 <a class="header-anchor" href="#场景演练-做一个待办事项" aria-label="Permalink to &quot;场景演练：做一个待办事项&quot;">​</a></h2><h3 id="第一轮-基础结构" tabindex="-1">第一轮：基础结构 <a class="header-anchor" href="#第一轮-基础结构" aria-label="Permalink to &quot;第一轮：基础结构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我写一个待办事项的基本结构</span></span></code></pre></div><p>Claude 会给你一个基本框架。</p><h3 id="第二轮-添加功能" tabindex="-1">第二轮：添加功能 <a class="header-anchor" href="#第二轮-添加功能" aria-label="Permalink to &quot;第二轮：添加功能&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>添加&quot;标记完成&quot;功能</span></span></code></pre></div><p>Claude 在现有基础上继续开发。</p><h3 id="第三轮-添加保存" tabindex="-1">第三轮：添加保存 <a class="header-anchor" href="#第三轮-添加保存" aria-label="Permalink to &quot;第三轮：添加保存&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>添加&quot;保存到文件&quot;功能</span></span></code></pre></div><p>Claude 继续完善。</p><h2 id="上下文的作用" tabindex="-1">上下文的作用 <a class="header-anchor" href="#上下文的作用" aria-label="Permalink to &quot;上下文的作用&quot;">​</a></h2><p>Claude 记得对话历史，所以：</p><ul><li>你不需要重复之前说的话</li><li>可以随时问&quot;现在的进度怎么样了&quot;</li></ul><h2 id="什么时候开新对话" tabindex="-1">什么时候开新对话？ <a class="header-anchor" href="#什么时候开新对话" aria-label="Permalink to &quot;什么时候开新对话？&quot;">​</a></h2><ul><li>对话太长了（超过几百条）</li><li>换了一个完全不相关的任务</li><li>想重新开始</li></ul><h2 id="清空对话" tabindex="-1">清空对话 <a class="header-anchor" href="#清空对话" aria-label="Permalink to &quot;清空对话&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/clear</span></span></code></pre></div><p>输入这个命令可以清空对话历史。</p><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><p>会基本的对话操作。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: Claude 忘了之前的对话？</strong></p><p>A: 超过一定长度可能遗忘，可以开新对话并简要描述背景。</p><p><strong>Q: 对话乱了？</strong></p><p>A: 输入 <code>/clear</code> 清空重来。</p><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p>用多轮对话方式，让 Claude 帮你做一个&quot;记账本&quot;程序。</p><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p>下一章我们会学习如何用 Claude 帮你调试代码。</p><p><a href="/guide/3-practical-workflows/08-debugging.html">👉 第八章：调试和错误处理</a></p>',36)])])}const b=e(s,[["render",o]]);export{c as __pageData,b as default};
